// 1. Recupera la serie di dati da Grafana
const series = context.panel.data.series[0];
if (!series || !series.fields) return {};

// 2. Trova le colonne basandoti sulle trasformazioni
const backendField = series.fields.find(f => f.name === 'approach');
const durationField = series.fields.find(f => f.name === 'spark-duration');

if (!backendField || !durationField) {
  return { title: { text: "Errore: Colonne 'approach' o 'spark-duration' non trovate.", left: "center" } };
}

const backendTypes = backendField.values.buffer || backendField.values;
const durationValues = durationField.values.buffer || durationField.values;

const rddValues = [];
const dataframeValues = [];
const sqlValues = [];

// Smista i tempi nei tre gruppi numerici
for (let i = 0; i < backendTypes.length; i++) {
  const type = String(backendTypes[i]).toUpperCase().trim();
  const duration = parseInt(durationValues[i], 10);

  if (isNaN(duration)) continue;

  if (type === 'RDD') rddValues.push(duration);
  else if (type === 'DATAFRAME') dataframeValues.push(duration);
  else if (type === 'SQL') sqlValues.push(duration);
}

// Funzione per calcolare Min, Q1, Mediana, Q3, Max e Outliers
function getBoxplotStats(data) {
  if (data.length === 0) return { box: [], outliers: [] };
  const sorted = [...data].sort((a, b) => a - b);
  const min = sorted[0];
  const max = sorted[sorted.length - 1];

  const getPercentile = (p) => {
    const idx = (sorted.length - 1) * p;
    const base = Math.floor(idx);
    const rest = idx - base;
    if (sorted[base + 1] !== undefined) {
      return sorted[base] + rest * (sorted[base + 1] - sorted[base]);
    }
    return sorted[base];
  };

  const q1 = getPercentile(0.25);
  const median = getPercentile(0.5);
  const q3 = getPercentile(0.75);

  const iqr = q3 - q1;
  const lowerBound = q1 - 1.5 * iqr;
  const upperBound = q3 + 1.5 * iqr;

  const outliers = [];
  const cleanData = [];

  sorted.forEach(v => {
    if (v < lowerBound || v > upperBound) {
      outliers.push(v);
    } else {
      cleanData.push(v);
    }
  });

  const finalMin = cleanData.length ? cleanData[0] : min;
  const finalMax = cleanData.length ? cleanData[cleanData.length - 1] : max;

  return {
    box: [finalMin, q1, median, q3, finalMax],
    outliers: outliers
  };
}

const rddStats = getBoxplotStats(rddValues);
const dfStats = getBoxplotStats(dataframeValues);
const sqlStats = getBoxplotStats(sqlValues);

const allOutliers = [
  ...rddStats.outliers.map(v => [0, v]),
  ...dfStats.outliers.map(v => [1, v]),
  ...sqlStats.outliers.map(v => [2, v])
];

// 5. Configurazione Grafica Renderizzata
return {
  title: {
