      // Allarga la dimensione delle candele riducendo lo spazio vuoto tra le colonne
      barCategoryGap: '25%',
      // Configurazione delle singole candele con colori dedicati e mediana evidenziata in rosso rosso
      data: [
        {
          value: rddStats.box,
          itemStyle: {
            color: 'rgba(230, 126, 34, 0.2)',
            borderColor: '#e67e22',
            borderWidth: 2
          }
        },
        {
          value: dfStats.box,
          itemStyle: {
            color: 'rgba(46, 204, 113, 0.2)',
            borderColor: '#2ecc71',
            borderWidth: 2
          }
        },
        {
          value: sqlStats.box,
          itemStyle: {
            color: 'rgba(155, 89, 182, 0.2)',
            borderColor: '#9b59b6',
