// 1. Recupera la stringa grezza inviata da Redis/Grafana
const series = context.panel.data.series[0];
if (!series) return {};

// Sostituisci 'value' con il nome reale del campo se la tua query usa un alias
const rawDataString = series.fields.find(f => f.name === 'value').values.buffer[0];
if (!rawDataString) return {};

// 2. Parsing della stringa (Separiamo i tempi per RDD, DATAFRAME e SQL)
const rddValues = [];
const dataframeValues = [];
const sqlValues = [];

// Usiamo una Regex per intercettare pattern come "8762RDD" o "7772DATAFRAME"
const regex = /(\d+)(RDD|DATAFRAME|SQL)/g;
let match;

while ((match = regex.exec(rawDataString)) !== null) {
  const duration = parseInt(match[1], 10);
  const type = match[2];

  if (type === 'RDD') rddValues.push(duration);
  if (type === 'DATAFRAME') dataframeValues.push(duration);
  if (type === 'SQL') sqlValues.push(duration);
}

// 3. Prepariamo i dati per il Box Plot tramite lo strumento nativo di ECharts
// Passiamo un array contenente i tre gruppi di dati
const boxplotData = echarts.dataTool.prepareBoxplotData([
  rddValues,
  dataframeValues,
  sqlValues
]);

// 4. Configurazione dell'interfaccia visiva del grafico
return {
  title: {
    text: 'Analisi Prestazioni Backend Spark (spark-duration)',
    left: 'center',
    textStyle: { color: '#e0e0e0', fontSize: 16 }
  },
  tooltip: {
    trigger: 'item',
    axisPointer: { type: 'shadow' }
  },
  grid: {
    left: '10%',
    right: '10%',
    bottom: '15%',
    top: '15%'
  },
  xAxis: {
    type: 'category',
    data: ['RDD', 'DATAFRAME', 'SQL'],
    axisLine: { lineStyle: { color: '#888' } },
    axisLabel: { textStyle: { color: '#ccc' } }
  },
  yAxis: {
    type: 'value',
    name: 'Durata (ms)',
    nameTextStyle: { color: '#ccc' },
    splitLine: { show: true, lineStyle: { color: '#333' } },
    axisLine: { lineStyle: { color: '#888' } },
    axisLabel: { textStyle: { color: '#ccc' } }
  },
  series: [
    {
      name: 'Distribuzione Durata',
      type: 'boxplot',
      data: boxplotData.boxData,
      itemStyle: {
        borderColor: '#569cd6',
        fill: '#1e1e1e',
        borderWidth: 2
      },
      // Formattiamo il popup al passaggio del mouse per leggere i quartili
      tooltip: {
        formatter: function (param) {
          return [
            '<b>Backend: ' + param.name + '</b>',
            'Massimo (Max): ' + param.data[5] + ' ms',
            'Q3 (75%): ' + param.data[4] + ' ms',
            'Mediana (50%): ' + param.data[3] + ' ms',
            'Q1 (25%): ' + param.data[2] + ' ms',
            'Minimo (Min): ' + param.data[1] + ' ms'
          ].join('<br/>');
        }
      }
    },
    {
      name: 'Outliers',
      type: 'scatter',
      data: boxplotData.outliers,
      itemStyle: { color: '#ff5c5c' }
    }
  ]
};
